INSERT INTO `nr_task` VALUES (26, 'Cuộc dạo chơi của Xên (26)', '[\"Thu thập capsule kì bí\r\nĐến võ đài Xên Bọ Hung\r\nTiêu diệt 7 đứa con của Xên\r\nTiêu diệt Siêu Bọ Hung\r\nBáo vớn Bunma tương lai\",\r\n\"Thu thập capsule kì bí\r\nĐến võ đài Xên Bọ Hung\r\nTiêu diệt 7 đứa con của Xên\r\nTiêu diệt Siêu Bọ Hung\r\nBáo vớn Bunma tương lai\",\r\n\"Thu thập capsule kì bí\r\nĐến võ đài Xên Bọ Hung\r\nTiêu diệt 7 đứa con của Xên\r\nTiêu diệt Siêu Bọ Hung\r\nBáo vớn Bunma tương lai\"]', '[[\"Thu thập capsule kì bí\",\"Đến võ đài Xên Bọ Hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Báo với Bunma tương lai\"],[\"Thu thập capsule kì bí\",\"Đến võ đài Xên Bọ Hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Báo với Bunma tương lai\"],[\"Thu thập capsule kì bí\",\"Đến võ đài Xên Bọ Hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Báo với Bunma tương lai\"]]\r\n', '[50,-1,7,1,-1]', '[[-1,-1,-1,-1,37],[-1,-1,-1,-1,37],[-1,-1,-1,-1,37]]', '[[-1,-1,-1,-1,102],[-1,-1,-1,-1,102],[-1,-1,-1,-1,102]]', '[[\"Thu thập Capsule kì bí\",\"Đến võ đài xên bọ hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Trả nhiệm vụ cho Bunma \"],[\"Thu thập Capsule kì bí\",\"Đến võ đài xên bọ hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Trả nhiệm vụ cho Bunma \"],[\"Thu thập Capsule kì bí\",\"Đến võ đài xên bọ hung\",\"Tiêu diệt 7 đứa con của Xên\",\"Tiêu diệt Siêu Bọ Hung\",\"Trả nhiệm vụ cho Bunma \"]]', 150000, 150000, 0, 0, 0);
INSERT INTO `nr_task` VALUES (27, 'Truy tìm Mabư (27)', '[\"Đến đại hội võ thuật gặp Osin sau đó đi theo hướng dẫn của Osin để truy tìm Mabu cũng như các đồng đảng của chúng\",\"Đến đại hội võ thuật gặp Osin sau đó đi theo hướng dẫn của Osin để truy tìm Mabu cũng như các đồng đảng của chúng.\",\"Đến đại hội võ thuật gặp Osin sau đó đi theo hướng dẫn của Osin để truy tìm Mabu cũng như các đồng đảng của chúng.\"]', '[[\"Đến Đại Hội Võ thuật gặp Osin\",\"Tiêu diệt 20 Drabura\",\"Tiêu diệt 20 BuiBui\",\"Tiệu diệt 20 Yacon\",\"Tiêu diệt 20 Mabu\",\"Quay trở lại trả nhiệm vụ cho Osin\"]\r\n,[\"Đến Đại Hội Võ thuật gặp Osin\",\"Tiêu diệt 20 Drabura\",\"Tiêu diệt 20 BuiBui\",\"Tiệu diệt 20 Yacon\",\"Tiêu diệt 20 Mabu\",\"Quay trở lại trả nhiệm vụ cho Osin\"]\r\n,[\"Đến Đại Hội Võ thuật gặp Osin\",\"Tiêu diệt 20 Drabura\",\"Tiêu diệt 20 BuiBui\",\"Tiệu diệt 20 Yacon\",\"Tiêu diệt 20 Mabu\",\"Quay trở lại trả nhiệm vụ cho Osin\"]]', '[-1,20,20,20,20,-1]', '[[44,-1,-1,-1,-1,44],[44,-1,-1,-1,-1,44],[44,-1,-1,-1,-1,44]]', '[[52,-1,-1,-1,-1,52],[52,-1,-1,-1,-1,52],[52,-1,-1,-1,-1,52]]', '[[\"Đến Đại Hội Võ thuật gặp Osin\",\"Tiêu diệt 20 Drabura\",\"Tiêu diệt 20 BuiBui\",\"Tiệu diệt 20 Yacon\",\"Tiêu diệt 20 Mabu\",\"Quay trở lại trả nhiệm vụ cho Osin\"]\r\n,[\"Đến Đại Hội Võ thuật gặp Osin\",\"Tiêu diệt 20 Drabura\",\"Tiêu diệt 20 BuiBui\",\"Tiệu diệt 20 Yacon\",\"Tiêu diệt 20 Mabu\",\"Quay trở lại trả nhiệm vụ cho Osin\"]\r\n,[\"Đến Đại Hội Võ thuật gặp Osin\",\"Tiêu diệt 20 Drabura\",\"Tiêu diệt 20 BuiBui\",\"Tiệu diệt 20 Yacon\",\"Tiêu diệt 20 Mabu\",\"Quay trở lại trả nhiệm vụ cho Osin\"]]', 0, 0, 0, 0, 0);
